/* ---------------------------------------------------------------
   Spam protection for public forms: hidden trap field, fill-time check,
   privacy consent, and an optional Cloudflare Turnstile check
--------------------------------------------------------------- */
function TurnstileBox({ onToken, widgetRef }) {
  const box = useRef(null);
  useEffect(() => {
    let cancelled = false;
    const mount = () => {
      if (cancelled || !box.current || !window.turnstile || widgetRef.current !== null) return;
      widgetRef.current = window.turnstile.render(box.current, {
        sitekey: SITE.turnstileKey,
        callback: (t) => onToken(t),
        "expired-callback": () => onToken(""),
        "error-callback": () => onToken(""),
      });
    };
    if (window.turnstile) mount();
    else {
      let s = document.getElementById("cf-turnstile-script");
      if (!s) {
        s = document.createElement("script");
        s.id = "cf-turnstile-script";
        s.src = "https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit";
        s.async = true;
        document.head.appendChild(s);
      }
      s.addEventListener("load", mount);
    }
    return () => { cancelled = true; };
  }, []);
  return <div ref={box} className="mb-4" />;
}

function useFormGuard() {
  const started = useRef(Date.now());
  const widget = useRef(null);
  const [hp, setHp] = useState("");
  const [consent, setConsent] = useState(false);
  const [token, setToken] = useState("");
  const ready = !SITE.turnstileKey || !!token;
  const payload = () => ({ hp, startedAt: started.current, consent, token });
  const reset = () => {
    setToken("");
    if (widget.current !== null && window.turnstile) window.turnstile.reset(widget.current);
  };
  const render = ({ withConsent = true } = {}) => (
    <>
      <div aria-hidden="true" style={{ position: "absolute", left: "-10000px", top: "auto", width: 1, height: 1, overflow: "hidden" }}>
        <label>Leave this field empty
          <input type="text" name="website" tabIndex={-1} autoComplete="off" value={hp} onChange={(e) => setHp(e.target.value)} />
        </label>
      </div>
      {withConsent && (
        <label className="flex items-start gap-2.5 text-sm mb-4 mt-2" style={{ color: INK_SOFT }}>
          <input type="checkbox" className="mt-1" checked={consent} onChange={(e) => setConsent(e.target.checked)} />
          <span>
            I have read the{" "}
            <a href="#privacy" target="_blank" rel="noopener noreferrer" className="underline" style={{ color: BLUE }}>privacy notice</a>{" "}
            and consent to StartupTN using the information I submit for the purposes it describes.
          </span>
        </label>
      )}
      {SITE.turnstileKey && <TurnstileBox onToken={setToken} widgetRef={widget} />}
    </>
  );
  return { consent, ready, payload, reset, render };
}

function ReferenceCard({ code }) {
  const [copied, setCopied] = useState(false);
  if (!code) return null;
  const copy = async () => {
    try { await navigator.clipboard.writeText(code); setCopied(true); setTimeout(() => setCopied(false), 2000); }
    catch { /* the code is on screen to copy by hand */ }
  };
  return (
    <div className="rounded-md border p-4 mb-8" style={{ borderColor: LINE, background: PAPER }}>
      <div className="text-xs font-semibold uppercase tracking-wide mb-1" style={{ color: SLATE }}>Your reference code</div>
      <div className="flex items-center justify-between gap-4">
        <div data-testid="ref-code" className="text-2xl font-semibold tracking-wider" style={{ color: INK, fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace" }}>{code}</div>
        <button type="button" onClick={copy} className="text-sm font-medium flex items-center gap-1.5" style={{ color: BLUE }}><Copy size={14} /> {copied ? "Copied" : "Copy"}</button>
      </div>
      <p className="text-xs mt-2" style={{ color: SLATE }}>
        Save this code now. It is shown only once and we cannot look it up for you. You will need it, with your email, to check your status.
      </p>
    </div>
  );
}

function QrCode({ value }) {
  const src = React.useMemo(() => {
    const q = qrcode(0, "M");
    q.addData(value);
    q.make();
    return q.createDataURL(4, 4);
  }, [value]);
  return <img src={src} alt="QR code to add this account to your authenticator app" style={{ imageRendering: "pixelated", background: "#fff", maxWidth: "100%" }} />;
}

