function StageTracker({ stage }) {
  const closed = stage === "Not Completed";
  const currentIdx = closed ? STAGES.length - 1 : STAGES.indexOf(stage);
  return (
    <div className="flex items-center">
      {STAGES.map((s, i) => {
        const done = i < currentIdx || (i === currentIdx && stage === "Completed");
        const active = i === currentIdx && stage !== "Completed";
        const dotColor = closed && i === STAGES.length - 1 ? RED : done ? BLUE : active ? GOLD : LINE;
        return (
          <React.Fragment key={s}>
            {i > 0 && <div className="h-px flex-1" style={{ background: i <= currentIdx ? BLUE : LINE, minWidth: 12 }} />}
            <div className="flex flex-col items-center gap-1.5 px-1">
              <div className="rounded-full" style={{ width: 10, height: 10, background: dotColor }} />
              <span className="text-xs whitespace-nowrap" style={{ color: active ? INK : SLATE, fontWeight: active ? 600 : 400 }}>
                {closed && i === STAGES.length - 1 ? "Closed" : s}
              </span>
            </div>
          </React.Fragment>
        );
      })}
    </div>
  );
}
