/* ---------------------------------------------------------------
   Public: Supply-side registration
--------------------------------------------------------------- */
function SupplyRegisterView({ setView, providers, setProviders, persist }) {
  const [form, setForm] = useState({
    contactName: "", designation: "", contactEmail: "", phone: "",
    name: "", category: PROVIDER_CATEGORIES[0], sector: SECTORS[0], capabilities: [],
    description: "", demoLink: "", ref1: "",
    smeApproach: "", smeTimeline: "",
  });
  const [done, setDone] = useState(false);
  const [ref, setRef] = useState("");
  const [saving, setSaving] = useState(false);
  const g = useFormGuard();
  const [error, setError] = useState("");
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  const setCategory = (e) => setForm((f) => ({ ...f, category: e.target.value, capabilities: [] }));
  const toggleCapability = (c) => setForm((f) => ({
    ...f, capabilities: f.capabilities.includes(c) ? f.capabilities.filter((x) => x !== c) : [...f.capabilities, c],
  }));

  const REQUIRED_FIELDS = [
    ["contactName", "contact person"], ["contactEmail", "email"], ["phone", "phone"],
    ["name", "organisation name"], ["description", "what you have built"],
    ["smeApproach", "what you would do for an SME"],
  ];

  const submit = async (e) => {
    e.preventDefault();
    if (saving) return;
    const missing = REQUIRED_FIELDS.filter(([k]) => !String(form[k] || "").trim());
    if (missing.length > 0) {
      setError(`Please complete the required fields marked * — missing: ${missing.map(([, label]) => label).join(", ")}.`);
      return;
    }
    setError("");
    const record = {
      id: newId(), ...form, track: "Established",
      hasDemo: !!form.demoLink.trim(), status: "Pending", submittedAt: new Date().toISOString(),
      scores: {}, totalScore: 0, tier: "",
    };
    const next = [...providers, record];
    if (!g.consent) { setError("Please tick the box to confirm you have read the privacy notice."); return; }
    if (!g.ready) { setError("Please complete the verification check."); return; }
    setSaving(true);
    try {
      const res = await persist("providers", next, g.payload());
      setRef(res?.ref || "");
      setProviders(next);
      setDone(true);
    } catch (err) {
      setError(err.status && err.status < 500 ? err.message : "We could not save your submission. Please check your connection and try again.");
      g.reset();
    } finally {
      setSaving(false);
    }
  };

  if (done) {
    return (
      <PageShell narrow>
        <ShieldCheck size={28} style={{ color: BLUE }} />
        <h2 className="aim-display text-2xl font-semibold mt-4 mb-2" style={{ color: INK }}>Application received</h2>
        <p className="text-sm leading-relaxed mb-6" style={{ color: SLATE }}>
          The Enablement Layer reviews new applications against the supply-side verification rubric.
          Statutory details (registration, GSTIN, PAN) are requested from shortlisted providers at the verification stage.
          Check back on the status page with your reference code and email.
        </p>
        <ReferenceCard code={ref} />
        <div className="flex gap-3">
          <Button variant="teal" onClick={() => setView("status-check")}>Check status</Button>
          <Button variant="ghost" onClick={() => setView("home")}>Back to home</Button>
        </div>
      </PageShell>
    );
  }

  return (
    <PageShell narrow>
      <BackLink setView={setView} />
      <h2 className="aim-display text-2xl font-semibold mb-1" style={{ color: INK }}>Register as a provider</h2>
      <p className="text-sm mb-8" style={{ color: SLATE }}>
        Verified before listed — not self-declared. Three short sections: who we should contact, what you have built,
        and what you would do for an SME.
      </p>
      <form onSubmit={submit}>
        <SectionHeading n={1} title="Whom should we contact?" />
        <div className="grid grid-cols-2 gap-4">
          <Field label="Contact person" required>
            <TextInput value={form.contactName} onChange={set("contactName")} required />
          </Field>
          <Field label="Designation">
            <TextInput value={form.designation} onChange={set("designation")} />
          </Field>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <Field label="Email" required>
            <TextInput type="email" value={form.contactEmail} onChange={set("contactEmail")} required />
          </Field>
          <Field label="Phone" required>
            <TextInput type="tel" value={form.phone} onChange={set("phone")} required />
          </Field>
        </div>
        <Field label="Organisation name" required>
          <TextInput value={form.name} onChange={set("name")} placeholder="e.g. Vellai Systems Pvt Ltd" required />
        </Field>

        <SectionHeading n={2} title="What have you built?" />
        <div className="grid grid-cols-2 gap-4">
          <Field label="Category" required>
            <Select options={PROVIDER_CATEGORIES} value={form.category} onChange={setCategory} />
          </Field>
          <Field label="Primary sector" required>
            <Select options={SECTORS} value={form.sector} onChange={set("sector")} />
          </Field>
        </div>
        <Field label="Capabilities" hint="Select what applies — this is what demand-side matching runs against.">
          <div className="grid gap-2">
            {CAPABILITY_OPTIONS[form.category].map((c) => (
              <label key={c} className="flex items-center gap-2.5 text-sm" style={{ color: INK_SOFT }}>
                <input type="checkbox" checked={form.capabilities.includes(c)} onChange={() => toggleCapability(c)}
                  style={{ accentColor: BLUE, width: 16, height: 16 }} />
                {c}
              </label>
            ))}
          </div>
        </Field>
        <Field label="What have you built?" required hint="Products or projects you have delivered, who used them, and the result.">
          <TextArea value={form.description} onChange={set("description")} required />
        </Field>
        <Field label="Demo or product link" hint="Optional">
          <TextInput value={form.demoLink} onChange={set("demoLink")} placeholder="https://" />
        </Field>
        <Field label="A client we can speak to" hint="Optional — name, organisation, contact">
          <TextInput value={form.ref1} onChange={set("ref1")} />
        </Field>

        <SectionHeading n={3} title="If we give you an opportunity to build for an SME" />
        <Field label="What would you do?" required hint="How you would approach it, what you would deliver, and how you would support the SME after hand-over.">
          <TextArea value={form.smeApproach} onChange={set("smeApproach")} required />
        </Field>
        <Field label="Typical timeline and engagement approach" hint="Optional — e.g. 6-week pilot, fixed price, monthly support">
          <TextInput value={form.smeTimeline} onChange={set("smeTimeline")} />
        </Field>

        {g.render()}
        {error && <div className="text-sm mb-4 mt-2" style={{ color: RED }}>{error}</div>}
        <Button type="submit" variant="teal" className="mt-2" disabled={saving}>{saving ? "Submitting…" : "Submit application"}</Button>
      </form>
    </PageShell>
  );
}

